}

impl<DT: Dispatch> ThreadToken<DT> {
    pub open spec fn wf2(&self, num_replicas: nat) -> bool {
        &&& self.rid.wf(num_replicas)
        &&& self.fc_client@.value().is_Idle()
        &&& (self.tid as nat)
            < MAX_THREADS_PER_REPLICA
        // &&& self.fc_client@@.instance == fc_inst

