#[verus::line_count::ignore]
#[verus::trusted]
#[verifier(external_body)]  /* vattr */
pub fn print_starvation_warning(line: u32) {
    eprintln!("WARNING({line}): has been looping for `WARN_THRESHOLD` iterations. Are we starving?");
}

#[verus::trusted]
#[verifier(external_body)]  /* vattr */
